const brief = $input.first().json.brief;
const pokeStatus = brief.includes("(Pokémon temporarily unavailable)") ? "failed" : "ok";
const dealStatus = brief.includes("(Game deals temporarily unavailable)") ? "failed" : "ok";
let runStatus = "ok";
if (pokeStatus === "failed" && dealStatus === "failed") {
  runStatus = "failed";
} else if (pokeStatus === "failed" || dealStatus === "failed") {
  runStatus = "degraded";
}
return [ { json: {
  timestamp: new Date().toLocaleString("en-IN", { timeZone: "Asia/Kolkata" }),
  run_status: runStatus,
  pokemon_status: pokeStatus,
  deals_status: dealStatus,
  brief_length: brief.length
} } ];

const deals = $input.all().map(i => i.json).filter(d => d && d.title);

// Guard: request failed, so no deal has a title
if (deals.length === 0) {
  return [ { json: { dealText: "🎮 Game Deals\n(Game deals temporarily unavailable)\n\n" } } ];
}

let text = "🎮 Top Game Deals (USD)\n";
deals.forEach(d => {
  const sale = parseFloat(d.salePrice);
  const normal = parseFloat(d.normalPrice);
  const savings = Math.round(parseFloat(d.savings));
  const price = sale === 0 ? "FREE" : "$" + sale.toFixed(2);
  text += "• " + d.title + ": " + price + " (was $" + normal.toFixed(2) + ", -" + savings + "%)\n";
  text += "  " + d.steamRatingText + ", deal score " + d.dealRating + "/10\n";
});

return [ { json: { dealText: text + "\n" } } ];

const items = $input.all();
let pokeText = "";
let dealText = "";
items.forEach(item => {
  if (item.json.pokeText) pokeText += item.json.pokeText;
  if (item.json.dealText) dealText += item.json.dealText;
});
const today = new Date().toLocaleDateString("en-IN", {
  timeZone: "Asia/Kolkata", weekday: "long", day: "numeric", month: "long", year: "numeric"
});
return [ { json: { subject: "Daily Brief: " + today, brief: "📅 " + today + "\n\n" + pokeText + dealText } } ];

const p = $input.first().json;

// Guard: request failed or response has no name
if (!p || !p.name) {
  return [ { json: { pokeText: "🎲 Pokémon of the Day\n(Pokémon temporarily unavailable)\n\n" } } ];
}

const types = p.types.map(t => t.type.name).join(", ");
const height = p.height / 10;
const weight = p.weight / 10;
const hp = p.stats.find(s => s.stat.name === "hp").base_stat;

const text = "🎲 Pokémon of the Day\n" +
  "#" + p.id + " " + p.name + " (" + types + ")\n" +
  "Height: " + height + " m, Weight: " + weight + " kg, HP: " + hp + "\n\n";

return [ { json: { pokeText: text } } ];
